SELECT json_object('obs','text','declined',CASE WHEN (SELECT text FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1) IS NULL THEN 1 ELSE 0 END,'value_kind','text','value',(SELECT text FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','page','ordinal',1),'provenance',NULL,'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)